/**
 * CSS output format.
 *
 * One format covers all four CSS files. It exists instead of the built-in
 * `css/variables` for two concrete reasons:
 *
 *  1. Themes need more than one selector. The dark theme must apply both when
 *     explicitly opted into (`[data-theme="dark"]`, which is what makes theme
 *     *nesting* work on a subtree) and when the OS asks for it, without that
 *     second rule stomping an explicit light subtree.
 *
 *  2. The generated files are meant to be read. Each token's `$description`
 *     is emitted above it, so opening theme-light.css tells you what the design
 *     language is doing rather than just what hex it resolved to.
 *
 * Everything else — reference resolution, `var()` output, value serialisation —
 * is delegated to Style Dictionary's own property formatter.
 */

import { createPropertyFormatter } from "style-dictionary/utils";

const INDENT = "  ";

/** Wrap `body` in one CSS rule per selector list, indented `depth` levels. */
function rule(selectors, body, depth = 0) {
  const pad = INDENT.repeat(depth);
  const head = selectors.map((s) => `${pad}${s}`).join(",\n");
  const inner = body
    .split("\n")
    .map((line) => (line.length > 0 ? pad + line : line))
    .join("\n");
  return `${head} {\n${inner}\n${pad}}`;
}

function banner({ description, sources }) {
  const lines = [
    "/**",
    " * Generated by Style Dictionary. Do not edit.",
    " *",
    ...String(description)
      .split("\n")
      .map((line) => ` * ${line}`.trimEnd()),
    " *",
    ` * Source: ${sources}`,
    " */",
  ];
  return lines.join("\n");
}

export const formats = [
  {
    name: "mash/css-vars",
    format: ({ dictionary, options }) => {
      const {
        selectors = [":root"],
        mediaQuery,
        mediaSelectors,
        description = "",
        sources = "",
        outputReferences = false,
        showDescriptions = true,
        usesDtcg = true,
      } = options;

      const formatProperty = createPropertyFormatter({
        outputReferences,
        dictionary,
        format: "css",
        usesDtcg,
        formatting: { indentation: INDENT },
      });

      const declarations = dictionary.allTokens
        .map((token, index) => {
          const declaration = formatProperty(token).replace(/\s*\/\*.*\*\/\s*$/, "");
          if (!showDescriptions || !token.$description) return declaration;
          // A blank line before each described token groups the file the same
          // way the source JSON is grouped: a lead token and its variants.
          const spacer = index === 0 ? "" : "\n";
          const comment = token.$description
            .split("\n")
            .map((line) => `${INDENT}/* ${line} */`)
            .join("\n");
          return `${spacer}${comment}\n${declaration}`;
        })
        .join("\n");

      const blocks = [rule(selectors, declarations)];

      if (mediaQuery && mediaSelectors) {
        blocks.push(`@media (${mediaQuery}) {\n${rule(mediaSelectors, declarations, 1)}\n}`);
      }

      return `${banner({ description, sources })}\n\n${blocks.join("\n\n")}\n`;
    },
  },
];

export function registerFormats(StyleDictionary) {
  for (const format of formats) {
    StyleDictionary.registerFormat(format);
  }
}
